/*
 * Example showing the creation of a userfaultfd object using syscall(2).
 * Compilation: gcc userfaultfd_create.c -o uffd_create
 */
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/syscall.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>

// Determine the appropriate syscall number for userfaultfd
#ifndef SYS_userfaultfd
    #ifdef __NR_userfaultfd
        #define SYS_userfaultfd __NR_userfaultfd
    #else
        #error "SYS_userfaultfd is not defined for this architecture."
    #endif
#endif

int main(void) {
    int uffd_fd;
    // Desired flags: Non-blocking and Close-on-exec
    int flags = O_NONBLOCK | O_CLOEXEC;

    // Use syscall(2) because glibc does not provide a wrapper
    uffd_fd = syscall(SYS_userfaultfd, flags);

    if (uffd_fd == -1) {
        fprintf(stderr, "Failed to create userfaultfd: %s\n", strerror(errno));

        if (errno == ENOSYS) {
            fprintf(stderr, "Error: userfaultfd is not supported by this kernel.\n");
        }
        return EXIT_FAILURE;
    }

    printf("Successfully created userfaultfd object.\n");
    printf("File Descriptor: %d\n", uffd_fd);

    // In a full application, further setup via ioctl(2) and fault handling via read(2) would follow.

    close(uffd_fd);
    return EXIT_SUCCESS;
}
